// Controller layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Connects the workflow and domain to the page. No business logic here.
import { useMachine } from "@xstate/react";
import { invoicesWorkflow } from "../workflow/invoices.workflow.js";
import * as domain from "../domain/invoices.domain.js";
import InvoicesPage from "../page/InvoicesPage.jsx";

export default function InvoicesController() {
  const [state, send] = useMachine(invoicesWorkflow);
  const { items, selectedId, error } = state.context;

  return (
    <InvoicesPage
      status={String(state.value)}
      error={error}
      invoiceCount={domain.invoiceCount(items)}
      totalBilled={domain.totalBilled(items)}
      largestInvoice={domain.largestInvoice(items)}
      syncedAt={domain.syncedAt(items)}
      rows={domain.toInvoiceRows(items)}
      selectedId={selectedId}
      formValues={domain.toFormValues(domain.findInvoice(items, selectedId))}
      onEdit={(id) => send({ type: "EDIT", id })}
      onDelete={(id) => send({ type: "DELETE", id })}
      onSave={(values) => send({ type: "SAVE", data: domain.toInvoiceInput(values) })}
      onCancel={() => send({ type: "CANCEL" })}
    />
  );
}
